  "Toutes les lignes des répertoires sélectionnés ont été examinées.": "चयनित आरंभिक प्रतिलेखन में सभी पंक्तियों की जांच की गई है।",
  "Le PGN de la position est invalide.": "पद PGN अमान्य है।",
  "Les transpositions ne sont pas disponibles après un coup nul pédagogique.": "अध्ययन शून्य शतरंज चाल के बाद स्थानांतरण उपलब्ध नहीं हैं।",
