  "Tous les thèmes et ouvertures, sans filtre personnalisé.": "सभी विषयों और उद्घाटन, बिना कस्टम फिल्टर.",
  "La difficulté progresse dans les limites de ta sélection. Les records sont séparés du Storm standard.": "आपके चयन में कठिनाई बढ़ जाती है। रिकॉर्ड मानक तूफान से अलग हैं।",
