  "Classique : dès une erreur ou une aide. Storm : après une mauvaise réponse.": "क्लासिकः एक गलती या सहायता के बाद। तूफानः गलत उत्तर के बाद।",
  "Les copies existantes et leurs annotations sont conservées, sans doublon dans la même base. Les anciennes tentatives ne sont pas copiées rétroactivement.": "मौजूदा प्रतियां और एनोटेशन एक ही डेटाबेस में डुप्लिकेट के बिना संरक्षित हैं। पिछले प्रयासों को पीछे की ओर से कॉपी नहीं किया जाता है।",
  "La solution du puzzle est indisponible. Recharge la page.": "शतरंज पहेली समाधान उपलब्ध नहीं है। पृष्ठ को पुनः लोड करें।",
  "Puzzles à revoir": "समीक्षा करने के लिए शतरंज पहेली",
  "Exercice ajouté à la base. Le puzzle est conservé.": "डेटाबेस में अभ्यास जोड़ा गया। आपका शतरंज पहेली संरक्षित है।",
  "La solution est préremplie. Tu peux la modifier ou ajouter des variantes.": "समाधान पहले से भरा हुआ है। आप इसे संपादित कर सकते हैं या बदलाव जोड़ सकते हैं।",
  "Revoir les puzzles joués": "समीक्षा खेला शतरंज पहेली",
  "La solution fournie pour cet exercice est invalide.": "प्रदान किया गया व्यायाम समाधान अमान्य है।",
  "La solution ne commence pas à la position choisie.": "समाधान चयनित स्थिति से शुरू नहीं होता है।",
  "Dès une erreur, un indice ou une solution affichée, le puzzle est ajouté à la base choisie. Cela s’applique aussi au puzzle classique en cours.": "एक गलती, एक संकेत या एक खुलासा समाधान के बाद, आपके द्वारा चुने गए डेटाबेस में शतरंज पहेली जोड़ी जाती है। यह वर्तमान क्लासिक शतरंज पहेली पर भी लागू होता है।",
  "Crée d’abord une base d’étude dans la bibliothèque.": "पहले पुस्तकालय में एक अध्ययन डेटाबेस बनाएं।",
  "Les copies existantes et leurs annotations sont conservées. L’historique et Puzzle Storm ne sont pas copiés automatiquement.": "मौजूदा प्रतियां और टिप्पणीएँ संरक्षित हैं। पिछले प्रयासों और शतरंज पहेली तूफान स्वचालित रूप से कॉपी नहीं किए जाते हैं।",
  "Réglages des puzzles enregistrés.": "शतरंज पहेली सेटिंग्स सहेजी गई।",
  "Déjà copié dans la bibliothèque.": "पहले से ही पुस्तकालय में कॉपी की गई है।",
