  "Les identifiants de la sélection doivent être des entiers positifs.": "चयन आईडी सकारात्मक पूर्णांक होना चाहिए।",
  "Une partie ou un exercice ne peut apparaître qu’une fois dans la sélection.": "एक शतरंज खेल या व्यायाम चयन में केवल एक बार दिखाई दे सकता है।",
