  "Le moteur n’a pas fourni de variante légale.": "शतरंज इंजन ने कानूनी बदलाव नहीं लौटाया।",
  "La partie a changé depuis sa mise en attente. Relance son analyse.": "शतरंज का खेल तब से बदल गया जब से यह कतार में था। उसके विश्लेषण को फिर से चलाएं।",
