  "Traitement interne invalide.": "अमान्य आंतरिक कार्य।",
  "Type de traitement invalide.": "अमान्य कार्य प्रकार।",
  "Options de traitement trop volumineuses.": "कार्य विकल्प बहुत बड़े हैं।",
