  "Base de recherche invalide.": "अवैध खोज डेटाबेस।",
  "Mode de recherche invalide.": "अमान्य खोज मोड।",
  "Cette partie dépasse la limite de positions indexables.": "यह शतरंज खेल सूचकांकित स्थिति सीमा से अधिक है।",
  "Cette partie dépasse la taille de l’index de positions.": "यह शतरंज खेल स्थिति सूचकांक आकार सीमा से अधिक है।",
