  "Aucune partie ou position PGN reconnue.": "कोई PGN शतरंज खेल या स्थिति मान्यता प्राप्त नहीं है।",
  "Le PGN contient des coups hors d’une partie ou ignorés par le lecteur.": "PGN में एक शतरंज खेल के बाहर या पार्सर द्वारा अनदेखी किए गए शतरंज चाल शामिल हैं।",
  "Cette action attend une seule partie PGN.": "इस क्रिया के लिए एक एकल PGN शतरंज खेल की आवश्यकता होती है।",
  "Chemin de variante invalide.": "अवैध भिन्नता पथ।",
  "Les informations PGN doivent être un objet de 150 champs au maximum.": "PGN मेटाडेटा एक ऑब्जेक्ट होना चाहिए जिसमें अधिकतम 150 फ़ील्ड हों।",
  "La ligne doit contenir entre 1 et 200 coups UCI.": "पंक्ति में 1 से 200 UCI शतरंज चाल के बीच होना चाहिए।",
  "Action de variante inconnue.": "अज्ञात भिन्नता क्रिया।",
  "Cette action placerait un coup nul pédagogique dans la ligne principale. Garde cette analyse dans une variante.": "यह मुख्य पंक्ति में एक निर्देशात्मक शून्य शतरंज चाल डाल देगा। इस विश्लेषण को भिन्नता में रखें।",
  "Cette première version prend en charge les échecs classiques.": "यह संस्करण मानक शतरंज का समर्थन करता है।",
