  "Nom de champ PGN invalide.": "अमान्य PGN फ़ील्ड नाम।",
  "FEN, SetUp et Variant se modifient avec l’éditeur de position.": "स्थिति संपादक का उपयोग करके FEN, सेटअप और वैरिएंट संपादित करें।",
  "Résultat PGN invalide.": "अमान्य PGN परिणाम।",
