  "Le code ECO doit aller de A00 à E99.": "ईसीओ कोड A00 से E99 तक होना चाहिए।",
  "Cadence PGN invalide. Exemple : 600+5 ou 40/7200:3600.": "अमान्य PGN समय नियंत्रण। उदाहरण: 600+5 या 40/7200:3600.",
  "Ce coup a été supprimé de la partie.": "इस शतरंज चाल को शतरंज के खेल से हटा दिया गया था।",
