  "Coup nul interdit dans la ligne principale ou en échec.": "मुख्य पंक्ति में या शैक में शून्य शतरंज चाल की अनुमति नहीं है।",
  "Plusieurs résultats dans la ligne principale.": "मुख्य पंक्ति में कई परिणाम।",
  "Résultat PGN non reconnu.": "PGN अनपहचान परिणाम।",
  "Filtre de classement invalide.": "अमान्य रेटिंग फ़िल्टर।",
  "Année invalide.": "अमान्य वर्ष।",
  "Identité de partie invalide.": "अमान्य शतरंज खेल पहचान।",
  "Position initiale ou variante non classique invalide.": "अमान्य प्रारंभिक स्थिति या गैर-मानक संस्करण।",
  "Résultat des en-têtes et des coups contradictoire.": "हेडर परिणाम और शतरंज चाल परिणाम संघर्ष।",
  "La lecture .zst nécessite le module zstandard.": ".zst फ़ाइलों को पढ़ने के लिए zstandard मॉड्यूल की आवश्यकता होती है.",
  "Le fichier ne contient plus le point de reprise enregistré.": "फ़ाइल में अब सहेजे गए चेकपॉइंट नहीं है।",
  "CHESSGYM_IMPORT_CACHE_MB doit être un entier de 64 à 4096.": "CHESSGYM_IMPORT_CACHE_MB 64 से 4096 तक की एक पूर्णांक होनी चाहिए।",
  "CHESSGYM_IMPORT_SORT_POSITIONS doit être 0 ou 1.": "CHESSGYM_IMPORT_SORT_POSITIONS 0 या 1 होना चाहिए।",
  "CHESSGYM_IMPORT_WORKERS doit être auto ou un entier de 1 à 16.": "CHESSGYM_IMPORT_WORKERS ऑटो या 1 से 16 तक का पूर्णांक होना चाहिए।",
  "Cette base n’est pas un répertoire d’ouvertures.": "यह डेटाबेस एक उद्घाटन आरंभ संग्रह नहीं है।",
  "Réglage d’examen inconnu.": "अज्ञात कवरेज स्कैन सेटिंग।",
  "Choisis un seuil de probabilité entre 0,01 % et 100 %.": "0.01% से 100% के बीच एक संभावना सीमा चुनें।",
  "Choisis un horizon de 1 à 60 demi-coups.": "आगे की गणना की सीमा 1 से 60 आधी चालों के बीच चुनें।",
  "Le choix de recommencer doit être vrai ou faux.": "पुनः आरंभ को सक्षम या निष्क्रिय किया जाना चाहिए।",
  "Un examen de ce répertoire est déjà en cours.": "पहले से ही इस आरंभिक संग्रह का स्कैन चल रहा है।",
  "Choisis des tranches de classement et des cadences Lichess valides.": "वैध Lichess रेटिंग बैंड और समय नियंत्रण चुनें।",
  "Le répertoire a changé pendant l’examen. Relance-le.": "स्कैन के दौरान उद्घाटन रिपरटोरियम बदल गया। इसे फिर से चलाओ.",
  "Le seuil de maîtrise doit être un entier de 1 à 3 650 jours.": "प्रवीणता की सीमा 1 से 3650 दिनों तक की एक पूर्णांक होनी चाहिए।",
  "Réglages de révision par défaut inconnus.": "अज्ञात डिफ़ॉल्ट समीक्षा सेटिंग्स।",
  "La limite de nouvelles cartes doit être un entier ou rester vide.": "नए कार्ड की सीमा एक पूर्णांक या खाली छोड़ दी जानी चाहिए।",
  "La période doit être de 7, 30, 90 ou 365 jours.": "अवधि 7, 30, 90 या 365 दिन होनी चाहिए।",
