  "Le pseudonyme doit contenir 2 à 50 lettres, chiffres, tirets ou traits de soulignement.": "उपयोगकर्ता नाम में 2-50 अक्षर, अंकों, हाइफ़न या रेखांकित होना चाहिए।",
