  "Le site refuse l’accès à ces parties publiques. Réessaie plus tard.": "साइट ने इन सार्वजनिक शतरंज खेलों तक पहुंच से इनकार कर दिया। बाद में फिर से प्रयास करें.",
  "Le site n’a pas fourni les parties. Réessaie plus tard.": "साइट में शतरंज के खेल उपलब्ध नहीं थे। बाद में फिर से प्रयास करें.",
