  "Le site a retourné une archive illisible.": "साइट ने एक अपठनीय अभिलेखागार लौटा दिया।",
  "Le site est temporairement inaccessible. Réessaie plus tard.": "साइट अस्थायी रूप से अनुपलब्ध है। बाद में फिर से प्रयास करें.",
