  "Cette carte ou sa progression a changé. Recharge la révision avant de la noter.": "यह कार्ड या उसकी प्रगति बदल गई। रेटिंग से पहले समीक्षा को पुनः लोड करें।",
  "Le PGN du répertoire ou de la partie source est invalide.": "प्रारंभिक प्रतिलेखा या स्रोत शतरंज खेल PGN अमान्य है।",
