  "La ligne source a changé. Vérifie à nouveau sa compatibilité.": "स्रोत लाइन बदल गई। इसकी संगतता की फिर से जांच करें।",
  "Le répertoire a changé. Vérifie à nouveau la ligne avant de l’ajouter.": "आरंभिक कार्यकलाप बदल गया। जोड़ने से पहले लाइन को फिर से जांचें।",
  "Cette tentative a déjà été enregistrée avec un autre résultat.": "यह प्रयास पहले से ही एक अलग परिणाम के साथ दर्ज किया गया था।",
  "Identifiant de brouillon invalide.": "अवैध मसौदा पहचान पत्र।",
  "Indique la révision du brouillon à enregistrer.": "सहेजने के लिए मसौदा की समीक्षा प्रदान करें।",
  "Ce brouillon a changé sur un autre appareil. Conserve ton brouillon local avant de choisir la version à reprendre.": "यह मसौदा एक और उपकरण पर बदल गया। फिर से किस संस्करण को चुनने से पहले अपने स्थानीय ड्राफ्ट को रखें।",
  "Le brouillon doit contenir un objet de données et sa révision.": "मसौदा में एक डेटा ऑब्जेक्ट और उसका संशोधन होना चाहिए।",
  "Ce brouillon dépasse la limite de 2 Mo. Sauvegarde la partie dans une base.": "यह मसौदा 2 एमबी की सीमा से अधिक है। एक डेटाबेस में शतरंज खेल सहेजें.",
  "Les brouillons occupent tout l’espace prévu. Sauvegarde ou supprime un brouillon avant de continuer.": "ड्राफ्ट भंडारण भरा है। आगे बढ़ने से पहले एक ड्राफ्ट को सहेजें या हटा दें।",
  "Les données du brouillon sont invalides.": "अवैध मसौदा डेटा।",
