  "Réglage de journée d’étude inconnu.": "अध्ययन के दिन की अज्ञात सेटिंग।",
  "Le début de journée doit être compris entre 0 et 23 heures.": "अध्ययन का दिन 0 से 23 घंटे के बीच शुरू होना चाहिए।",
  "Cet identifiant de séance a déjà été utilisé avec d’autres options.": "इस सत्र आईडी का पहले से ही विभिन्न विकल्पों के साथ उपयोग किया गया है।",
  "Cette base n’est pas activée pour les révisions.": "इस डेटाबेस के लिए समीक्षाएँ सक्षम नहीं हैं।",
  "Profil de ressources inconnu.": "अज्ञात संसाधन प्रोफ़ाइल।",
  "Profil de ressources invalide.": "अमान्य संसाधन प्रोफ़ाइल।",
  "Réserve au moins deux fils de calcul aux deux moteurs Stockfish.": "दो Stockfish शतरंज इंजनों के लिए कम से कम दो कंप्यूटिंग थ्रेड आरक्षित करें।",
