  "Fréquences exactes des parties déjà importées. Les résultats de cette position très fréquente seront disponibles après la fin de l’importation.": "पहले से ही आयात किए गए शतरंज खेलों के लिए सटीक आवृत्तियां। इस आम स्थिति के परिणाम आयात समाप्त होने के बाद उपलब्ध होंगे।",
  "Résultats indisponibles pendant l’importation; la fréquence reste exacte.": "आयात के दौरान परिणाम उपलब्ध नहीं हैं; आवृत्ति सटीक बनी हुई है।",
