  "Le PGN et l’historique d’édition sont conservés. Les réglages de révision de la destination s’appliquent ; la progression de révision précédente ne sera pas transférée.": "PGN और संपादन इतिहास संरक्षित हैं। गंतव्य की समीक्षा सेटिंग्स लागू होती हैं; पिछली समीक्षा प्रगति को स्थानांतरित नहीं किया जाएगा।",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires. Les copies utilisent les réglages de la destination. Les positions d’ouverture déjà apprises dans cette base gardent leur progression.": "एक स्वतंत्र प्रति में सभी शतरंज चाल, भिन्नताएं और टिप्पणियां शामिल होंगी। यह गंतव्य की सेटिंग्स का उपयोग करता है। पहले से ही वहां सीखी गई पदों को खोलने से उनकी प्रगति बनी रहती है।",
