  "Indique le chemin sur le PC ou le serveur qui héberge Chess Gym. Le fichier est lu progressivement, sans le téléverser depuis cet appareil.": "ChessGym होस्टिंग वाले पीसी या सर्वर पर पथ दर्ज करें। फ़ाइल को इस डिवाइस से अपलोड किए बिना सीधे स्ट्रीम किया जाता है।",
  "Maximum de parties à lire · vide = tout le fichier": "पढ़ने के लिए अधिकतम शतरंज खेल · रिक्त = पूरी फ़ाइल",
