  "Appliquer l’annotation": "टिप्पणी लागू करें",
  "Recharge ChessGym pour utiliser la sauvegarde manuelle. Les modifications de cette ancienne fenêtre n’ont pas été enregistrées.": "मैनुअल बचत का उपयोग करने के लिए ChessGym को पुनः लोड करें। इस पुरानी खिड़की से बदलाव सहेजे नहीं गए।",
  "Brouillon repris. La partie dans la base reste inchangée jusqu’à Sauvegarder.": "ड्राफ्ट फिर से शुरू हुआ। जब तक आप सहेजें क्लिक नहीं करते तब तक डेटाबेस शतरंज खेल अपरिवर्तित रहता है।",
  "Appliquer au brouillon": "मसौदे के लिए आवेदन करें",
  "La partie reste inchangée dans la base jusqu’à Sauvegarder.": "जब तक आप सहेजें क्लिक नहीं करते तब तक डेटाबेस शतरंज खेल अपरिवर्तित रहता है।",
  "Annotation appliquée au brouillon. Sauvegarde la partie pour la conserver dans la base.": "मसौदे पर लागू सूचना। डेटाबेस में रखने के लिए शतरंज खेल सहेजें।",
  "Informations PGN appliquées au brouillon. Sauvegarde la partie pour les conserver dans la base.": "PGN मसौदे पर लागू जानकारी। डेटाबेस में रखने के लिए शतरंज खेल सहेजें।",
  "Reprendre la séance en cours. Les modifications restent en brouillon tant que tu ne sauvegardes pas.": "वर्तमान सत्र को फिर से शुरू करें। जब तक आप बचत नहीं करते तब तक परिवर्तन ड्राफ्ट में रहते हैं।",
  "Préparation des statistiques exactes de cette position…": "इस स्थिति के लिए सटीक आंकड़े तैयार करना ...",
  "Préparation des statistiques exactes de cette position. Elles apparaîtront automatiquement dès que le calcul sera terminé.": "इस स्थिति के लिए सटीक आंकड़े तैयार करना। गणना पूरी होने पर वे स्वचालित रूप से दिखाई देंगे।",
  "Ce calcul a dépassé le délai disponible. Réessaie dans un instant ou choisis une position plus avancée.": "यह गणना उपलब्ध समय से अधिक थी। जल्द ही फिर से प्रयास करें या बाद की स्थिति चुनें।",
  "Statistiques exactes des parties importées. Les parties rejetées pendant l’importation sont exclues.": "आयातित शतरंज खेलों के लिए सटीक आंकड़े। आयात के दौरान अस्वीकार किए गए शतरंज खेलों को बाहर रखा गया है।",
  "Les résultats apparaîtront automatiquement dès qu’ils seront prêts.": "परिणाम तैयार होने पर स्वचालित रूप से दिखाई देंगे।",
  "La préparation continue sur le serveur. Clique sur Actualiser pour vérifier le résultat.": "सर्वर पर तैयारी जारी है। परिणाम की जांच करने के लिए Refresh पर क्लिक करें।",
  "Actualisation interrompue. Clique sur Actualiser pour réessayer.": "रिफ्रेश बाधित. पुनः प्रयास करने के लिए Refresh पर क्लिक करें।",
  "Cette partie est trop longue pour être exportée depuis cet éditeur. Utilise l’export de la base.": "यह शतरंज खेल इस संपादक से निर्यात करने के लिए बहुत लंबा है। डेटाबेस निर्यात का उपयोग करें।",
