  "Évaluation après ce coup, du point de vue des Blancs : + favorise les Blancs, − les Noirs.": "इस शतरंज चाल के बाद मूल्यांकन, व्हाइट के दृष्टिकोण सेः + व्हाइट को पसंद करता है, − ब्लैक को पसंद करता है।",
