  "Dernières données connues affichées.": "नवीनतम उपलब्ध डेटा दिखा रहा है।",
  "Cadences Lichess": "Lichess समय नियंत्रण",
  "Classement Lichess moyen des deux joueurs": "दोनों खिलाड़ियों की औसत Lichess रेटिंग",
  "· filtres actifs": "· फ़िल्टर सक्रिय",
  "· toutes les parties": "· सभी शतरंज खेल",
  "Elo minimum · chaque joueur": "न्यूनतम Elo · प्रत्येक खिलाड़ी",
  "Elo maximum · chaque joueur": "अधिकतम Elo · प्रत्येक खिलाड़ी",
  "Sans minimum": "न्यूनतम नहीं",
  "Cadences du PGN": "PGN समय नियंत्रण",
  "Sans maximum": "अधिकतम नहीं",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "कोई चयन नहीं = अज्ञात सहित सभी समय नियंत्रण।",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo PGN से आता है और दोनों खिलाड़ियों के लिए रेंज के भीतर होना चाहिए। Elo के बिना शतरंज खेलों को जब सीमा निर्धारित की जाती है तो बाहर रखा जाता है। PGN समय नियंत्रणों को याद या अनजान किया गया है \"अज्ञात\" है। इन शतरंज खेलों को समय नियंत्रणों का चयन करते समय बाहर रखा जाता है, जब तक कि \"अज्ञात\" का चयन नहीं किया जाता है।",
  ": indique un nombre valide pour la borne Elo.": ": Elo पंक्ति के लिए वैध संख्या दर्ज करें।",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": 0 से 4000 तक एक पूर्णांक Elo दर्ज करें, या बंधा हुआ रिक्त छोड़ दें।",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": न्यूनतम Elo अधिकतम Elo से अधिक नहीं हो सकता।",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "एक डेटाबेस बनाएँ और पुस्तकालय में PGN शतरंज खेल आयात करें।",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess मास्टर्स में Elo या टाइम-कंट्रोल फिल्टर नहीं है। एक मास्टर संग्रह को फ़िल्टर करने के लिए, मेगा डेटाबेस जैसे आयातित डेटाबेस चुनें।",
  "Source principale": "मुख्य स्रोत",
  "Mes bases PGN": "मेरे PGN डेटाबेस",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "केवल मुख्य पंक्ति के शतरंज चालों की गिनती की जाती है। विश्लेषण संबंधी भिन्नताएँ सांख्यिकी को भड़काती नहीं हैं।",
  "Référence dans chaque ligne": "प्रत्येक पंक्ति में संदर्भ",
  "Comparer avec": "तुलना करें",
  "Mes bases de référence": "मेरे संदर्भ डेटाबेस",
  "Aucune référence": "कोई संदर्भ नहीं",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "ये फ़िल्टर मुख्य डेटाबेस से स्वतंत्र हैं। प्रतिशत चयनित संदर्भ में इस स्थिति में शतरंज आंदोलन आवृत्ति को दर्शाता है।",
  "Probabilité de rencontre": "मुलाकात की संभावना",
  "Afficher la probabilité de la ligne": "रेखा की संभावना दिखाएं",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "खोजकर्ता में सीधे अपना पक्ष चुनें। केवल प्रतिद्वंद्वी के उत्तर ही मायने रखते हैं; आपके शतरंज चालों को माना जाता है। यह अनुमान प्रदर्शित भिन्नता और चयनित डेटाबेस फ़िल्टर का अनुसरण करता है। PGN के लिए एक आरेख से शुरू होने के लिए, यह उस प्रारंभिक स्थिति पर निर्भर करता है।",
  "Mode d’analyse": "विश्लेषण मोड",
  "Rapide (~250 ms par coup)": "त्वरित (~ 250 ms प्रति शतरंज चाल)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "अधिक गहराई विश्लेषण को परिष्कृत करती है और इसमें अधिक समय लगता है। 8 से 30 तक, प्रति शतरंज चाल 10 सेकंड की सीमा के साथ। यदि लक्ष्य प्राप्त नहीं होता है, तो ≈ परिणाम को चिह्नित करता है; इसकी वास्तविक गहराई देखने के लिए तैरें।",
  "Chargement de la connexion…": "लोड कनेक्शन...",
