  "Cette connexion est gérée dans la configuration du serveur.": "यह कनेक्शन सर्वर कॉन्फ़िगरेशन में प्रबंधित किया जाता है।",
  "Crée un jeton sans cocher de permissions, puis colle-le ici. Il reste sur ton serveur.": "अनुमतियों का चयन किए बिना एक टोकन बनाएं, फिर इसे यहां पेस्ट करें। यह आपके सर्वर पर रहता है।",
