  "Le jeton doit contenir de 8 à 2048 caractères, sans espaces.": "टोकन में 8 से 2048 वर्ण होना चाहिए, कोई रिक्त स्थान नहीं होना चाहिए।",
  "Impossible de modifier la connexion. Réessaie dans un moment.": "कनेक्शन नहीं बदल सकता था। जल्द ही फिर से प्रयास करें।",
