  "Nouvelle base de révision · Résoudre · Hybride. Toutes les variantes saisies seront acceptées comme solutions.": "नई समीक्षा डेटाबेस · हल · हाइब्रिड। सभी प्रविष्ट भिन्नताओं को समाधान के रूप में स्वीकार किया जाएगा।",
  "Position à jouer contre le moteur : les coups de solution sont facultatifs.": "शतरंज इंजन के खिलाफ खेलने के लिए स्थितिः समाधान शतरंज चाल वैकल्पिक हैं।",
  "Position à jouer contre le moteur. Active les révisions dans les réglages de cette base pour la retrouver dans Révisions.": "शतरंज इंजन के खिलाफ खेलने के लिए स्थिति। इस डेटाबेस की सेटिंग्स में समीक्षाओं को सक्षम करें ताकि इसे समीक्षाओं में पाया जा सके।",
  "Chaque décision de ton camp sera révisée séparément ; les variantes saisies fournissent les réponses acceptées.": "आपके पक्ष के लिए प्रत्येक निर्णय की अलग-अलग समीक्षा की जाती है; दर्ज किए गए परिवर्तन स्वीकार किए गए उत्तर प्रदान करते हैं।",
  "Toutes les variantes saisies seront acceptées comme solutions dans cet exercice.": "इस अभ्यास के समाधान के रूप में दर्ज किए गए सभी परिवर्तनों को स्वीकार किया जाएगा।",
  "Active les révisions dans les réglages de cette base pour y retrouver cet exercice.": "इस डेटाबेस की सेटिंग्स में समीक्षाओं को सक्षम करें इस अभ्यास को वहां खोजने के लिए।",
  "Création…": "बनाने के लिए ...",
  "Donne un titre à cet exercice.": "इस अभ्यास के लिए एक शीर्षक दर्ज करें।",
  "Joue au moins un coup pour définir la solution. Pour enregistrer un simple diagramme à jouer, choisis une base de type « Jouer contre le moteur ».": "समाधान को परिभाषित करने के लिए कम से कम एक शतरंज चाल खेलें। खेलने के लिए एक आरेख को सहेजने के लिए, \"शैक इंजन के खिलाफ खेलें\" प्रकार का डेटाबेस चुनें।",
