  "Deux versions de ton travail existent. Ouvre « Travail conservé » depuis le badge de l’analyse pour choisir celle à reprendre.": "आपके काम के दो संस्करण हैं। विश्लेषण बैज से \"बचत काम\" खोलें और चुनें कि कौन सा फिर से शुरू करना है।",
  "Le stockage de cet appareil est indisponible ou plein. Ton travail reste en mémoire : sauvegarde le PGN avant de fermer.": "इस उपकरण पर भंडारण अनुपलब्ध या पूर्ण है। आपका काम अभी भी स्मृति में हैः बंद करने से पहले PGN सहेजें।",
  "Le brouillon est conservé sur cet appareil, mais sa synchronisation est en attente.": "ड्राफ्ट इस डिवाइस पर सहेजा गया है, लेकिन सिंक्रनाइज़ेशन लंबित है.",
  "Brouillon · conflit": "मसौदा · संघर्ष",
