  "Deux versions existent. Choisir laquelle reprendre.": "दो संस्करण हैं। फिर से शुरू करने के लिए चुनें।",
  "Le brouillon est conservé en mémoire. Vérifier sa sauvegarde.": "मसौदा अभी भी स्मृति में है। जांचें कि यह सहेजा गया है।",
  "Brouillon synchronisé sur ton compte; Sauvegarder l’inscrit dans le PGN.": "ड्राफ्ट आपके खाते के साथ सिंक्रनाइज़ किया गया है; सेव इसे PGN पर लिखता है।",
  "Brouillon conservé sur cet appareil; Sauvegarder l’inscrit dans le PGN.": "इस डिवाइस पर सहेजा गया मसौदा; सहेजें इसे PGN पर लिखता है।",
  "La partie est enregistrée dans sa base.": "शतरंज का खेल अपने डेटाबेस में सहेजा गया है।",
  "La partie a changé dans la base. Ton brouillon est conservé; enregistre une copie ou recharge la partie avant de modifier la version de la base.": "डेटाबेस में शतरंज का खेल बदल गया है। आपका ड्राफ्ट संरक्षित है; डेटाबेस संस्करण को संपादित करने से पहले एक प्रति सहेजें या शतरंज खेल को फिर से लोड करें।",
  "La partie source a été supprimée. Ton brouillon reste disponible pour en sauvegarder une copie.": "स्रोत शतरंज खेल हटा दिया गया था। आपका ड्राफ्ट अभी भी प्रतिलिपि के रूप में सहेजने के लिए उपलब्ध है।",
  "Reprends une séance ou une analyse conservée sur ton compte.": "अपने खाते में सहेजे गए सत्र या विश्लेषण को फिर से शुरू करें।",
  "La reprise est conservée sur cet appareil. La synchronisation sera disponible lorsque le serveur sera mis à jour.": "आपकी प्रगति इस डिवाइस पर सहेजी गई है। सर्वर अपडेट होने के बाद सिंक्रनाइज़ेशन उपलब्ध होगा।",
