  "Glisser pour déplacer ou réordonner · cliquer pour choisir un dossier · Alt + ↑ / ↓ pour réordonner": "स्थानांतरित करने या फिर से क्रम · ड्रैग करने के लिए फ़ोल्डर · Alt + ↑ / ↓ चुनने के लिए फिर से क्रम करने के लिए क्लिक करें",
