  "Tu peux aussi glisser la base vers un dossier, ou entre deux bases pour changer leur ordre. Au clavier, Alt + ↑ / ↓ sur la poignée change son ordre.": "आप एक फ़ोल्डर में डेटाबेस को खींच सकते हैं, या दो डेटाबेस के बीच क्रम बदलने के लिए। कीबोर्ड के साथ फिर से क्रमबद्ध करने के लिए हैंडल पर Alt + ↑ / ↓ का उपयोग करें।",
