  "Nom": "नाम",
  "Catégories libres, séparées par des virgules": "मुक्त रूप की श्रेणियाँ, अल्पविरामों से अलग",
  "Cette base sert de référence à l’explorer et à la recherche de positions. Pour travailler une partie ou la réviser, ouvre-la dans l’analyse et sauvegarde une copie dans une base personnelle.": "यह डेटाबेस खोजकर्ता और स्थान खोज के लिए एक संदर्भ है। किसी शतरंज खेल का अध्ययन या समीक्षा करने के लिए, उसे विश्लेषण में खोलें और व्यक्तिगत डेटाबेस में एक प्रति सहेजें।",
  "Fichier source": "स्रोत फ़ाइल",
  "Fichier importé sur la machine hébergeant Chess Gym.": "Chess Gym होस्टिंग कंप्यूटर पर आयातित फ़ाइल।",
  "La sauvegarde complète inclut les parties de référence importées. Conserve aussi le fichier source pour pouvoir poursuivre une importation.": "पूर्ण बैकअप में आयातित संदर्भ शतरंज खेल शामिल हैं। आयात को फिर से शुरू करने के लिए स्रोत फ़ाइल को भी रखें।",
  "Enregistrer les réglages": "सेटिंग्स सहेजें",
  "Retirer cette base": "इस डेटाबेस को हटाएँ",
  "Les modifications sont enregistrées, mais la liste n’a pas pu être actualisée. Recharge la base pour la mettre à jour. ": "परिवर्तन सहेजे गए हैं, लेकिन सूची को अपडेट नहीं किया जा सका। डेटाबेस को अद्यतन करने के लिए पुनः लोड करें। ",
  "La partie a été supprimée de la base. Son analyse ouverte est conservée comme copie libre.": "शतरंज का खेल डेटाबेस से हटा दिया गया था। इसका खुला विश्लेषण एक मुक्त प्रति के रूप में संरक्षित है।",
  "Les informations PGN sont enregistrées. Rouvre la partie pour actualiser les temps des coups. ": "PGN जानकारी सहेजी गई है। शतरंज चाल के समय को अपडेट करने के लिए शतरंज खेल को फिर से खोलें। ",
  "Aucune partie à afficher": "प्रदर्शित करने के लिए कोई शतरंज खेल नहीं",
  "Essaie un autre terme de recherche.": "एक अलग खोज शब्द का प्रयोग करें।",
  "Ajoute ton compte ci-dessus, puis clique sur Synchroniser.": "ऊपर अपने खाते को जोड़ें, फिर सिंक्रनाइज़ करें पर क्लिक करें.",
  "Importe un fichier PGN ou sauvegarde une position dans cette base.": "PGN फ़ाइल आयात करें या इस डेटाबेस में एक स्थिति सहेजें।",
  "Incluse dans les révisions": "समीक्षाओं में शामिल",
