  "Hybride · résultat modifiable": "हाइब्रिड · समायोज्य परिणाम",
  "Les coups d’ouverture sont évalués individuellement. Les positions à résoudre ou à jouer ont leur propre historique.": "खुलने वाले शतरंज चालों को व्यक्तिगत रूप से वर्गीकृत किया जाता है। हल करने या खेलने के लिए स्थितियों का अपना इतिहास होता है।",
  "Priorité des coups d’ouverture": "उद्घाटन शतरंज चाल प्राथमिकता",
  "Fréquence de rencontre": "मुलाकात की आवृत्ति",
  "Ordre des échéances": "समाप्ति तिथि क्रम",
  "La fréquence utilise la dernière exploration « À compléter » de ce répertoire. Les reprises et les anciens retards restent prioritaires. Sans statistiques, l’ordre habituel est conservé.": "फ्रीक्वेंसी इस आरंभिक प्रतिलेखन के नवीनतम \"कवरगेज रिक्तियों\" स्कैन का उपयोग करता है। रीलिर्निंग और पुराने देर से आने वाले कार्ड प्राथमिकता रखते हैं। बिना आंकड़ों के, सामान्य क्रम बरकरार रहता है।",
  "Force Stockfish · 0 à 20": "Stockfish कौशल · 0 से 20",
  "Camp au trait": "जिस पक्ष की चाल है",
  "Gagner la position": "पद जीतें",
  "Convertir un avantage": "लाभ को परिवर्तित करें",
  "Tenir la nulle": "ड्रॉ बनाए रखें",
  "La force 0–20 est le réglage du moteur, sans équivalence Elo annoncée. L’analyse reste à pleine force.": "कौशल 0-20 एक शतरंज इंजन सेटिंग है, जिसमें Elo समकक्षता का दावा नहीं है। विश्लेषण हमेशा पूर्ण शक्ति का उपयोग करता है।",
  "Espacement et charge de travail": "अंतराल और कार्यभार",
  "L’espacement est adaptatif : chaque réussite allonge le délai de la carte. Les valeurs ci-dessous sont les délais minimaux, avec un plafond pour les reprises.": "अंतराल समायोज्य हैः प्रत्येक सफलता कार्ड के अंतराल को बढ़ाती है। नीचे दिए गए मान न्यूनतम अंतराल हैं, जिसमें भविष्य की समीक्षाओं के लिए अधिकतम है।",
