  "Un répertoire principal blanc et un noir servent de référence depuis tous les échiquiers.": "प्रत्येक शतरंज बोर्ड से एक प्राथमिक सफेद और एक प्राथमिक काला उद्घाटन रिपेरिटरी संदर्भ के रूप में उपलब्ध है।",
  "Supprimer cette base": "इस डेटाबेस को हटाना",
  "Mémoriser, résoudre et jouer. Chaque base possède ses propres réglages.": "याद रखें, हल करें और खेलें। प्रत्येक डेटाबेस की अपनी सेटिंग्स होती है।",
