  "Plusieurs ouvertures pour chaque camp, avec une principale blanche et noire.": "प्रत्येक पक्ष के लिए कई उद्घाटन, जिसमें एक प्राथमिक सफेद और काला उद्घाटन रिपरट्यूर है।",
  "Construis ton premier répertoire": "अपनी पहली उद्घाटन प्रतिलेखा बनाओ",
  "Active l’usage Répertoire dans les réglages d’une base. Les nouvelles lignes s’ajoutent depuis un échiquier compatible.": "डेटाबेस सेटिंग्स में प्रतिलेखन खोलने को सक्षम करें. एक संगत शतरंज बोर्ड से नई पंक्तियों को जोड़ें।",
  " coups à apprendre · ": " सीखने के लिए शतरंज चाल · ",
