  "Le suivi de lecture n’a pas pu être chargé. Rouvre la partie pour réessayer.": "पढ़ने की प्रगति को लोड नहीं किया जा सका। फिर से कोशिश करने के लिए शतरंज खेल फिर से खोलें.",
  "La lecture de cette base est terminée.": "इस डेटाबेस को पढ़ना पूरा है।",
  "Le statut « Nouveau » n’a pas pu être mis à jour. Il sera réessayé à la prochaine ouverture.": "\"नई\" स्थिति को अद्यतन नहीं किया जा सका। यह फिर से कोशिश की जाएगी जब आप अगले खेल खोलने.",
  "Joue un premier coup ou colle un PGN.": "पहला शतरंज चाल खेलें या PGN पेस्ट करें।",
  "Reprise…": "फिर से शुरू ...",
  "Reprendre la séance en cours. Le commentaire en cours est sauvegardé.": "वर्तमान सत्र को फिर से शुरू करें। वर्तमान टिप्पणी सहेजी गई है।",
  "Signet déplacé.": "बुकमार्क स्थानांतरित.",
  "Continuation supprimée. Tu peux l’annuler.": "निरंतरता हटा दी गई है। आप इसे रद्द कर सकते हैं.",
