  "Cette partie a été déplacée. Rouvre sa base pour actualiser la liste.": "इस शतरंज खेल को स्थानांतरित कर दिया गया था। सूची को ताज़ा करने के लिए अपने डेटाबेस को फिर से खोलें।",
  "La position de cet exercice a changé. La partie complète est ouverte à son point de départ.": "इस अभ्यास की स्थिति बदल गई है। पूर्ण शतरंज खेल अपनी प्रारंभिक स्थिति पर खुला है।",
  "La séance de révision n’est plus active.": "समीक्षा सत्र अब सक्रिय नहीं है।",
  "Sauvegardes": "बैकअप",
  "La sauvegarde personnelle contient tes bases de travail, annotations, réglages, brouillons et historique de révision. Elle exclut les grandes bases de référence.": "व्यक्तिगत बैकअप में आपके अध्ययन डेटाबेस, टिप्पणी, सेटिंग्स, मसौदा और समीक्षा इतिहास शामिल हैं। इसमें बड़े संदर्भ डेटाबेस को बाहर रखा गया है।",
  "Ce serveur propose la sauvegarde complète, qui contient également les grandes bases de référence.": "यह सर्वर एक पूर्ण बैकअप प्रदान करता है, जिसमें बड़े संदर्भ डेटाबेस भी होते हैं।",
  "Sauvegarde personnelle": "व्यक्तिगत बैकअप",
  "Sauvegarde complète": "पूर्ण समर्थन",
  "La sauvegarde complète inclut toutes les références importées et peut être très volumineuse. Conserve aussi leurs fichiers sources pour poursuivre une importation.": "पूर्ण बैकअप में सभी आयातित संदर्भ शामिल हैं और बहुत बड़ा हो सकता है। यदि आपको आयात को फिर से शुरू करने की आवश्यकता है तो उनकी स्रोत फ़ाइलों को भी रखें।",
