  "Le brouillon a changé. Rouvre la liste avant de le supprimer.": "ड्राफ्ट बदल गया। इसे हटाने से पहले सूची को फिर से खोलें।",
  "La synchronisation est indisponible. Le brouillon reste conservé.": "सिंक अनुपलब्ध है। ड्राफ्ट अभी भी बचा है।",
  "Résous le conflit avant de supprimer ce brouillon.": "इस मसौदे को हटाने से पहले संघर्ष को हल करें।",
  "Le compte ouvert a changé.": "साइन-इन खाता बदल गया है।",
  "Supprimer ce brouillon et ses annotations non enregistrées ? L’échiquier actuel sera réinitialisé; les parties enregistrées dans les bases sont conservées.": "इस मसौदे और उसके सहेजे गए नोटों को हटा दें? वर्तमान शतरंज बोर्ड को रीसेट किया जाएगा; डेटाबेस में सहेजे गए शतरंज खेल बनाए रखे जाएंगे।",
  "Supprimer ce brouillon et ses annotations non enregistrées ? Les parties enregistrées dans les bases sont conservées.": "इस मसौदे और उसके सहेजे गए नोटों को हटा दें? डेटाबेस में सहेजे गए शतरंज खेलों को रखा जाता है।",
