  "Un fichier du moteur installé a été modifié. Conservez cette version et choisissez un autre dossier.": "एक स्थापित शतरंज इंजन फ़ाइल बदल गई है। इस संस्करण को रखें और एक और फ़ोल्डर चुनें।",
  "L’installation n’a pas de manifeste de vérification.": "संयंत्र में कोई सत्यापन पत्र नहीं है।",
