  "Dans le dossier de ChessGym, ouvre « Restaurer ChessGym.cmd » et choisis ton archive.": "ChessGym फ़ोल्डर में, \"Restaurer ChessGym.cmd\" खोलें और अपना संग्रह चुनें।",
