  "Les coups joués ici ne modifient ni la partie ni son brouillon.": "यहां खेले जाने वाले शतरंज के कदम शतरंज के खेल या उसके ड्राफ्ट को नहीं बदलते हैं।",
  "Bien trouvé ! Tu peux maintenant comparer les suites.": "अच्छी तरह से पाया! अब आप निरंतरता की तुलना कर सकते हैं।",
  "Il existe un coup plus solide. Essaie encore.": "एक मजबूत शतरंज चाल है। फिर से कोशिश करो.",
