  "Essaie de jouer avec {piece}.": "{piece} को स्थानांतरित करने की कोशिश करें।",
  "Cherche les échecs, les prises et les menaces.": "चेक, कैप्चर और धमकियों की तलाश करें।",
  "Un mat forcé était disponible avant ce coup et ne l’est plus dans l’analyse.": "इस शतरंज चाल से पहले एक मजबूर साथी उपलब्ध था और अब विश्लेषण में नहीं मिला है।",
  "Ce coup permet à l’adversaire un mat forcé selon l’analyse.": "विश्लेषण के अनुसार, यह शतरंज चाल प्रतिद्वंद्वी को एक मजबूर साथी की अनुमति देती है।",
  "L’avantage disponible avant ce coup est fortement réduit ou perdu.": "इस शतरंज चाल से पहले लाभ काफी कम हो जाता है या खो जाता है।",
  "La position devient plus difficile à défendre selon le moteur.": "शतरंज इंजन स्थिति का बचाव करना अधिक कठिन मानता है।",
  "La position reste favorable, mais la conversion devient moins sûre.": "स्थिति अनुकूल बनी हुई है, लेकिन लाभ का रूपांतरण कम निश्चित है।",
  "Ce coup dégrade l’évaluation de la position selon le moteur.": "इस शतरंज चाल से शतरंज इंजन की स्थिति का आकलन खराब हो जाता है।",
  "Le coup précédent offrait une occasion favorable qui n’a pas été conservée.": "पिछले शतरंज कदम ने एक अवसर प्रदान किया जो बरकरार नहीं रखा गया था।",
  "Le PGN enregistré ne permet pas cette comparaison.": "इस तुलना के लिए सहेजे गए PGN का उपयोग नहीं किया जा सकता है।",
  "Cette partie commence par une position FEN. Le parcours depuis la position initiale est nécessaire pour vérifier la sortie du répertoire.": "यह शतरंज खेल FEN स्थिति से शुरू होता है। यह जांचने के लिए पूरे आंदोलन अनुक्रम की आवश्यकता होती है कि यह उद्घाटन प्रतिलेखन को कहां छोड़ता है।",
  "La ligne principale contient un coup nul d’analyse et ne représente pas une partie jouée.": "मुख्य पंक्ति में विश्लेषण शून्य शतरंज चाल होती है और यह एक खेला गया शतरंज खेल का प्रतिनिधित्व नहीं करती है।",
  "Choisis un répertoire pour ce camp.": "इस पक्ष के लिए एक उद्घाटन प्रतिलेखन चुनें।",
  "Aucun répertoire n’est défini pour ce camp.": "इस पक्ष के लिए कोई उद्घाटन प्रतिगामी परिभाषित नहीं है।",
  "Ce répertoire dépasse la limite de comparaison. Choisis un répertoire plus petit.": "यह उद्घाटन प्रतिलेखा तुलना की सीमा से अधिक है। एक छोटी सी आरंभिक धारावाहिक चुनें।",
  "Une partie du répertoire contient un PGN invalide. Corrige-la avant de comparer cette ligne.": "एक आरंभिक अनुक्रम शतरंज खेल में एक अमान्य PGN होता है। इस रेखा की तुलना करने से पहले इसे सुधारें।",
  "Le répertoire ne contient pas de ligne jouable depuis la position initiale.": "आरंभिक प्रतिले में प्रारंभिक स्थिति से कोई प्ले करने योग्य रेखा नहीं है।",
