  "Copier automatiquement les parties terminées": "स्वचालित रूप से तैयार शतरंज खेलों को कॉपी करें",
  "Toutes tes parties sont conservées dans l’historique du mode ordinateur. Cette option ajoute une copie dans la base choisie lorsqu’une partie se termine.": "आपके सभी शतरंज खेल कंप्यूटर शतरंज खेल इतिहास में बनाए रखे गए हैं। यह विकल्प एक शतरंज खेल समाप्त होने पर चयनित पुस्तकालय में एक प्रति जोड़ता है।",
  "Une seule copie par partie et par base. Les parties déjà terminées ne sont pas copiées rétroactivement.": "प्रत्येक पुस्तकालय में प्रति शतरंज खेल एक प्रति। पूर्व में समाप्त शतरंज खेलों की प्रतियां प्रतिवर्ती रूप से कॉपी नहीं की जाती हैं।",
