  "La synchronisation de cette partie est en attente.": "यह शतरंज खेल सिंक्रनाइज़ करने के लिए इंतजार कर रहा है।",
  "L’historique local est illisible. Sa copie est conservée.": "स्थानीय इतिहास को नहीं पढ़ा जा सकता है। इसकी प्रति संरक्षित है।",
  "Cette partie a des suites différentes sur cet appareil et dans l’historique. Les deux copies sont conservées.": "इस उपकरण और अभिलेखागार में इस शतरंज खेल के विभिन्न निरंतरता है। दोनों प्रतियां संरक्षित हैं।",
  "Une copie locale de cette partie attend sa synchronisation. Elle est conservée avant d’ouvrir une autre version.": "इस शतरंज खेल की एक स्थानीय प्रति सिंक्रनाइज़ करने के लिए इंतजार कर रहा है। इसे एक और संस्करण खोलने से पहले संरक्षित किया जाता है।",
  "La partie reste conservée sur cet appareil. Réessaie sa synchronisation avant de commencer une autre partie.": "इस डिवाइस पर शतरंज का खेल बरकरार है। एक और शतरंज खेल शुरू करने से पहले इसे फिर से सिंक्रनाइज़ करने का प्रयास करें।",
  "Indique la révision de la partie à enregistrer.": "सहेजने के लिए शतरंज खेल के संशोधन को निर्दिष्ट करें।",
  "Cette partie a changé sur un autre appareil. Recharge son historique avant de la reprendre.": "यह शतरंज का खेल एक और उपकरण पर बदल गया। फिर से शुरू करने से पहले इसके इतिहास को फिर से लोड करें।",
  "La base de destination est introuvable.": "गंतव्य पुस्तकालय नहीं मिला।",
  "Choisis une base personnelle, plutôt qu’une base de référence.": "संदर्भ डेटाबेस के बजाय व्यक्तिगत पुस्तकालय चुनें।",
