  "Les séances en cours ou interrompues sont exclues des résultats. Les mesures absentes restent indiquées par —.": "सक्रिय और बाधित सत्रों को परिणामों से बाहर रखा गया है। अनुपलब्ध माप को - के रूप में दर्शाया गया है।",
  "La limite quotidienne de nouvelles cartes est atteinte. Reprends la séance pour continuer les autres révisions.": "दैनिक नए कार्ड की सीमा तक पहुंच गई है। अन्य समीक्षाओं को जारी रखने के लिए सत्र को फिर से शुरू करें।",
  "Cette carte a déjà été travaillée depuis la préparation de la séance.": "सत्र की तैयारी के बाद से इस कार्ड पर पहले ही अभ्यास किया जा चुका है।",
  "Cette réponse a déjà été enregistrée ou sa base a changé.": "यह उत्तर पहले ही दर्ज किया गया है या इसका डेटाबेस बदल गया है।",
  "Une base choisie est indisponible ou ses révisions sont désactivées.": "एक चयनित डेटाबेस अनुपलब्ध है या इसकी समीक्षाएँ अक्षम हैं।",
