  "Maximum de nouveaux exercices aujourd’hui": "आज के अधिकतम नए अभ्यास",
  "La durée est un objectif de temps actif. Tu peux terminer la carte en cours, faire une pause et reprendre plus tard.": "अवधि एक सक्रिय अध्ययन समय लक्ष्य है। आप वर्तमान कार्ड को समाप्त कर सकते हैं, विराम और बाद में फिर से शुरू कर सकते हैं।",
