  "{count} exercices pour cette séance": "इस सत्र के लिए {count} अभ्यास",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les paramètres et limites de chaque base sont conservés.": "व्यक्तिगत त्रुटियां और असफल शतरंज पहेली आपके सक्रिय डेटाबेस में पहले से ही अभ्यास से आती हैं। प्रत्येक डेटाबेस अपनी सेटिंग्स और सीमाओं को रखता है।",
  "Actualise l’aperçu pour vérifier cette sélection.": "इस चयन की जांच करने के लिए पूर्वावलोकन को ताज़ा करें।",
  "Préparation de l’aperçu…": "पूर्वावलोकन की तैयारी...",
  "La séance respecte les échéances et les limites quotidiennes.": "सत्र में समय सीमा और दैनिक सीमाओं का सम्मान किया जाएगा।",
  "Aucun exercice disponible pour cette sélection aujourd’hui.": "इस चयन के लिए आज कोई अभ्यास उपलब्ध नहीं है।",
  "Préparation de la séance…": "तैयारी सत्र...",
  "Vérifier et reprendre": "जांच और फिर से शुरू करें",
  "La création de la séance est en attente de confirmation. Réessaie pour retrouver la même séance.": "सत्र निर्माण की पुष्टि का इंतजार है। उसी सत्र को पुनः प्राप्त करने का पुनः प्रयास करें।",
  "La séance est prête. Termine le coup en cours pour l’ouvrir.": "सत्र तैयार है। इसे खोलने के लिए वर्तमान शतरंज चाल को पूरा करें।",
  "Mettre la séance en pause": "विराम सत्र",
  "Conserver dans les appris avec des rappels d’entretien espacés": "रखरखाव की याददाश्तों के साथ सीखा हुआ रखें",
  "Marquer comme maîtrisé avec entretien des acquis": "रखरखाव समीक्षाओं के साथ मास्टर के रूप में अंक",
  "{count} exercices maîtrisés. Des rappels d’entretien espacés préservent ces acquis.": "{count} अभ्यास में महारत हासिल की। अंतरित रखरखाव समीक्षाएं उन्हें बनाए रखने में मदद करती हैं।",
  "Les prochaines reprises respectent les réglages de chaque base.": "आगामी समीक्षाएं प्रत्येक डेटाबेस की सेटिंग्स का सम्मान करती हैं।",
  "Entretenir les cartes maîtrisées": "मास्टर कार्ड बनाए रखें",
  "Rappel d’entretien · jours": "रखरखाव अंतराल · दिन",
  "Maximum de rappels par jour": "प्रति दिन अधिकतम अनुस्मारक",
  "Les acquis restent conservés. Les premiers rappels des anciennes cartes sont répartis dans le temps, sous ce plafond quotidien. Une erreur remet la carte en apprentissage.": "आपकी प्रगति संरक्षित है। मौजूदा कार्डों के लिए प्रारंभिक अनुस्मारक समय के साथ इस दैनिक सीमा के भीतर फैलाए जाते हैं। एक गलती कार्ड को सीखने के लिए लौटा देती है।",
  "Les cartes au-delà de ce seuil deviennent maîtrisées. Leur historique est conservé et les rappels suivent les réglages d’entretien ci-dessous.": "इस सीमा से परे कार्ड मास्टर हो जाते हैं। उनका इतिहास संरक्षित है और अनुस्मारक नीचे रखरखाव सेटिंग्स का पालन करते हैं।",
  "{count} rappels d’entretien dus": "{count} रखरखाव समीक्षाएं",
  " cartes actives. Les rappels des cartes maîtrisées suivent tes réglages d’entretien. ": " सक्रिय कार्ड। मास्टर कार्ड अनुस्मारक आपकी रखरखाव सेटिंग्स का पालन करें। ",
  "Aucun exercice disponible. Les cartes maîtrisées suivent leurs rappels d’entretien. Vérifie les parties sélectionnées et les réponses enregistrées dans cette base.": "कोई व्यायाम उपलब्ध नहीं है। मास्टर कार्ड अपने रखरखाव कार्यक्रम का पालन करते हैं। इस डेटाबेस में चयनित शतरंज खेलों और सहेजे गए उत्तरों की जांच करें।",
  "{count} résultats sur {total} parties": "{total} शतरंज खेलों से {count} परिणाम",
