  "Ce bloc ressemble à un bloc existant. Vérifie que tu souhaites deux objectifs distincts.": "यह ब्लॉक एक मौजूदा ब्लॉक जैसा दिखता है। जांचें कि क्या आप दो अलग-अलग लक्ष्य चाहते हैं।",
