  "Aucune carte disponible pour ce bloc. Ajuste les révisions de la base ou choisis une autre activité.": "इस ब्लॉक के लिए कोई कार्ड उपलब्ध नहीं है। डेटाबेस समीक्षाओं को समायोजित करें या किसी अन्य गतिविधि का चयन करें।",
  "Cette ressource de lecture est indisponible. Vérifie les réglages de la base.": "यह रीडिंग संसाधन उपलब्ध नहीं है। डेटाबेस सेटिंग्स की जांच करें।",
  "Cette base ne contient aucune partie à lire.": "इस डेटाबेस में पढ़ने के लिए कोई शतरंज खेल नहीं है।",
