  "Une autre révision est en cours. Reprends-la depuis Révisions avant de lancer ce bloc.": "एक और समीक्षा चल रही है। इस ब्लॉक शुरू करने से पहले समीक्षा से इसे फिर से शुरू करें।",
  "Cette activité se déclare depuis le programme.": "कार्यक्रम से इस गतिविधि को रिकॉर्ड करें।",
  "Le contexte de cette lecture a changé. Rouvre le bloc depuis le programme.": "यह पाठ का संदर्भ बदल गया। अपने कार्यक्रम से ब्लॉक फिर से खोलें।",
  "Partie étudiée enregistrée.": "अध्ययन शतरंज खेल रिकॉर्ड किया गया।",
  "Le suivi de lecture reste à synchroniser. Réessaie avant de terminer ce bloc.": "पढ़ने की प्रगति को अभी भी सिंक्रनाइज़ करने की आवश्यकता है। इस ब्लॉक को खत्म करने से पहले पुनः प्रयास करें।",
