  "Choisis les ressources à télécharger, puis lance leur installation.": "डाउनलोड करने के लिए संसाधन चुनें, फिर उनका इंस्टॉलेशन शुरू करें।",
  "Ouvre une édition pour télécharger son fichier et l’importer dans ChessGym.": "किसी संस्करण का विवरण खोलें, उसकी फ़ाइल डाउनलोड करें और उसे ChessGym में आयात करें।",
  "Téléchargements sélectionnés": "चुने गए डाउनलोड",
  "{count} sélectionné(s)": "{count} चयनित",
  "Entretien des ressources": "संसाधनों का रखरखाव",
  "Ces mises à jour concernent les moteurs et les bases installées.": "ये अपडेट इंस्टॉल किए गए इंजन और डेटाबेस पर लागू होते हैं।",
  "Détails et import": "विवरण और आयात",
  "Détails de la ressource": "संसाधन का विवरण",
  "Commence avec les exemples, puis ajoute les ressources qui te sont utiles.": "उदाहरणों से शुरुआत करें, फिर अपनी ज़रूरत के संसाधन जोड़ें।",
  "Essayer ChessGym en quelques minutes": "कुछ मिनटों में ChessGym आज़माएँ",
  "Trois petites bases incluses, utilisables sans téléchargement. Leurs lignes et commentaires pédagogiques sont proposés sous CC0.": "तीन छोटे डेटाबेस शामिल हैं, जिन्हें बिना डाउनलोड इस्तेमाल कर सकते हैं। उनकी शैक्षिक चालें और टिप्पणियाँ CC0 के अंतर्गत उपलब्ध हैं।",
  "Apprendre une ouverture avec quelques lignes commentées.": "टिप्पणियों वाली कुछ चालों से एक ओपनिंग सीखें।",
  "Retrouver les coups d’une courte partie pédagogique.": "एक छोटी शैक्षिक बाज़ी में चालें खोजें।",
  "Lire une partie commentée et retrouver ta progression.": "टिप्पणियों वाली बाज़ी पढ़ें और अपनी प्रगति सहेजें।",
  "Ouvrir {activity}": "{activity} खोलें",
  "Tes bases d’exemples sont prêtes. Tes modifications et ta progression sont conservées.": "आपके उदाहरण डेटाबेस तैयार हैं। आपके बदलाव और प्रगति सुरक्षित रहते हैं।",
  "Stockfish est nécessaire pour noter les coups dans Guess the Move. Le répertoire et la lecture sont disponibles sans moteur.": "Guess the Move में चालों का मूल्यांकन करने के लिए Stockfish चाहिए। रेपर्टरी और पढ़ना इंजन के बिना उपलब्ध हैं।",
  "Recommandé pour commencer": "शुरुआत के लिए अनुशंसित",
  "Facultatif · adversaire au style humain": "वैकल्पिक · इंसानों जैसी शैली वाला प्रतिद्वंद्वी",
  "Stockfish active l’analyse et Guess the Move. Maia est facultatif pour jouer contre un adversaire au style humain. Aucun téléchargement ne commence avant ton choix.": "Stockfish विश्लेषण और Guess the Move उपलब्ध कराता है। इंसानों जैसी शैली वाले प्रतिद्वंद्वी से खेलने के लिए Maia वैकल्पिक है। आपके चुनने पर ही डाउनलोड शुरू होते हैं।",
  "Exemples ajoutés. Choisis une activité pour commencer.": "उदाहरण जोड़ दिए गए। शुरू करने के लिए एक गतिविधि चुनें।",
  "Dont {time} estimées d’après la cadence": "इसमें समय नियंत्रण के आधार पर अनुमानित {time} शामिल है",
  "Dont {time} calculées à partir des pendules": "इसमें घड़ियों से गणना किया गया {time} शामिल है",
