  "Temps historique": "मूल बाज़ी में लिया गया समय",
  "Complément de temps": "अतिरिक्त समय",
  "Écart cumulé": "कुल अंतर",
  "Écart cumulé : {delta}": "कुल अंतर: {delta}",
