  "Et {count} autres…": "और {count} अन्य…",
  "Les parties sélectionnées seront supprimées de cette base de référence. Le fichier PGN original est conservé. Cette action ne peut pas être annulée.": "चुनी गई बाज़ियाँ इस संदर्भ डेटाबेस से हटा दी जाएँगी। मूल PGN फ़ाइल सुरक्षित रहेगी। इस कार्रवाई को पूर्ववत नहीं किया जा सकता।",
  "Les parties seront copiées dans la base choisie, puis supprimées de cette base de référence. Le fichier PGN original est conservé.": "बाज़ियाँ चुने गए डेटाबेस में कॉपी की जाएँगी, फिर इस संदर्भ डेटाबेस से हटा दी जाएँगी। मूल PGN फ़ाइल सुरक्षित रहेगी।",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires.": "सभी चालों, विविधताओं और टिप्पणियों सहित एक स्वतंत्र कॉपी बनाई जाएगी।",
  "{count} partie supprimée.": "{count} बाज़ी हटा दी गई।",
  "{count} parties supprimées.": "{count} बाज़ियाँ हटा दी गईं।",
  "{count} partie dupliquée.": "{count} बाज़ी की कॉपी बनाई गई।",
  "{count} parties dupliquées.": "{count} बाज़ियों की कॉपी बनाई गई।",
  "{count} partie déplacée.": "{count} बाज़ी स्थानांतरित की गई।",
  "{count} parties déplacées.": "{count} बाज़ियाँ स्थानांतरित की गईं।",
  "Sélectionne des parties pour les dupliquer, les déplacer ou les supprimer. Pour les annoter ou les réviser, duplique-les dans une base personnelle. L’explorer et la recherche de positions utilisent la ligne principale des parties de référence.": "बाज़ियों को कॉपी करने, स्थानांतरित करने या हटाने के लिए चुनें। उनमें टिप्पणियाँ जोड़ने या उनका अभ्यास करने के लिए उन्हें निजी डेटाबेस में कॉपी करें। एक्सप्लोरर और स्थिति खोज संदर्भ बाज़ियों की मुख्य लाइन का उपयोग करते हैं।",
  "Reprends la partie pour continuer.": "जारी रखने के लिए बाज़ी फिर से शुरू करें।",
  "Reconstruction non effectuée": "पुनर्निर्माण छोड़ दिया गया",
  "Tout réviser": "सभी दोहराएँ",
  "Tout apprendre": "सभी सीखें",
  "Un lancement attend une confirmation. Réessaie le même choix pour retrouver tes cartes.": "सत्र शुरू करने के लिए पुष्टि की प्रतीक्षा है। अपने कार्ड वापस पाने के लिए वही विकल्प दोबारा चुनें।",
  "Réviser / Apprendre": "दोहराएँ / सीखें",
  "Cartes à travailler": "अध्ययन के लिए कार्ड",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les révisions dues passent avant les nouvelles cartes.": "निजी गलतियाँ और असफल पहेलियाँ आपके सक्रिय डेटाबेस में पहले से मौजूद अभ्यासों से आती हैं। जिन कार्डों की पुनरावृत्ति का समय आ गया है, वे नए कार्डों से पहले आते हैं।",
  "La sélection ne correspond pas au bloc du programme.": "चयन कार्यक्रम के ब्लॉक से मेल नहीं खाता।",
  "Réviser seulement": "केवल दोहराएँ",
  "Apprendre seulement": "केवल सीखें",
  "Réviser + Apprendre": "दोहराएँ + सीखें",
  "Les révisions dues passent avant les nouvelles cartes. Le volume dépend de l’objectif du bloc.": "जिन कार्डों की पुनरावृत्ति का समय आ गया है, वे नए कार्डों से पहले आते हैं। अभ्यास की मात्रा ब्लॉक के लक्ष्य पर निर्भर करती है।",
  "Les révisions dues passent avant les nouvelles cartes.": "जिन कार्डों की पुनरावृत्ति का समय आ गया है, वे नए कार्डों से पहले आते हैं।",
  "Aucune nouvelle carte": "कोई नया कार्ड नहीं है",
  "Toutes les cartes disponibles ont déjà été travaillées.": "सभी उपलब्ध कार्ड पहले ही पढ़े जा चुके हैं।",
  "Aucune révision due. Tu peux apprendre de nouvelles cartes.": "अभी कोई पुनरावृत्ति देय नहीं है। आप नए कार्ड सीख सकते हैं।",
  "Espacement des révisions": "पुनरावृत्तियों के बीच अंतराल",
  " nouvelles cartes disponibles pour apprendre.": " नए कार्ड सीखने के लिए उपलब्ध हैं।",
  "Le calendrier et les séries de jours utilisent la même journée d’étude.": "कैलेंडर और लगातार अध्ययन किए गए दिनों की गणना में अध्ययन दिवस की एक ही परिभाषा लागू होती है।",
  "Ces objectifs proposent une pause sans modifier les échéances. Tu peux les adapter au lancement.": "ये लक्ष्य पुनरावृत्ति की तारीखें बदले बिना विराम का सुझाव देते हैं। आप शुरू करते समय इन्हें बदल सकते हैं।",
  "Choisis les bases à mettre à jour avec les valeurs globales Manqué, Difficile, Bien et Facile. Les échéances et l’historique restent conservés.": "जिन डेटाबेस को «फिर से», «कठिन», «अच्छा» और «आसान» की वैश्विक सेटिंग्स से अपडेट करना है, उन्हें चुनें। नियत तारीखें और इतिहास सुरक्षित रहते हैं।",
  "Ouvrir mes parties": "मेरे शतरंज खेल खोलें",
  "Temps estimé d’après la cadence": "समय नियंत्रण के आधार पर अनुमानित समय",
  "Temps calculé à partir des pendules": "घड़ियों से गणना किया गया समय",
