  "Le travail de tes activités prévues apparaîtra ici au fur et à mesure de son enregistrement.": "आपकी नियोजित गतिविधियों का कार्य दर्ज होते ही यहाँ दिखाई देगा।",
  "Les activités compatibles comptent automatiquement dans ton programme.": "संगत गतिविधियाँ आपके कार्यक्रम में अपने-आप गिनी जाती हैं।",
  "L’attribution automatique est désactivée dans tes aides et ajustements.": "सहायता और समायोजन में स्वचालित आवंटन बंद है।",
